// The git version check of setup.
// The config hooks of claudetto (`commit-msg` and `pre-push`) run only on git 2.54 or later.
// An older git ignores the `GIT_CONFIG_*` keys with no error, so setup must say it.

/** The oldest git that reads `GIT_CONFIG_COUNT` hooks. */
export const GIT_MIN = [2, 54] as const;

/** The major and minor number of the output of `git --version`, such as `git version 2.54.0 (Apple Git-157)`, or `undefined`. */
export const parseGitVersion = (
  text: string,
): { major: number; minor: number } | undefined => {
  const m = /git version (\d+)\.(\d+)/.exec(text);
  return m === null ? undefined : { major: Number(m[1]), minor: Number(m[2]) };
};

/** True when the version in `text` is `GIT_MIN` or later. */
export const gitIsNew = (text: string): boolean => {
  const v = parseGitVersion(text);
  if (v === undefined) return false;
  return v.major !== GIT_MIN[0] ? v.major > GIT_MIN[0] : v.minor >= GIT_MIN[1];
};
